94-// Did a change to `file` touch only its comments? `before`/`after` are the file's
95-// two contents, null where it was added or deleted — neither of which is a
96-// comment-only change, whatever the other side holds.
97-//
98-// Indentation and blank lines are ignored, so a whitespace-only edit inside a
99-// template literal reads as comments-only; in a language whose indentation is
100-// semantic the extension set above has already answered no.
101-//
102-// Its callers grant a PERMISSION on the answer — may this run land its own pull
103-// request unreviewed, may it have touched this file at all — which is why the safe
104-// end is "no" and why the answer lives here rather than in each of them.
105-export function commentOnly(file, before, after) {
106-  if (before == null || after == null) return false;
107-  const dot = file.lastIndexOf('.');
108-  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
109:  if (!COMMENT_CHECKABLE.has(ext)) return false;
110-  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
111-  return meat(before) === meat(after);
112-}

